  @Test
  void bhvSerializationObject116PositiveOffsetIsPreservedInTheSerializedString() {
    OffsetDateTime dt =
        OffsetDateTime.of(2024, 1, 15, 10, 30, 0, 0, ZoneOffset.ofHoursMinutes(5, 30));
    assertTrue(ObjectSerializer.stringify(dt).endsWith("+05:30"));
  }
